-- postgresql.conf: wal_level = logical (restart required)
CREATE PUBLICATION cdc_pub FOR TABLE shop.orders, shop.customers;

-- full old row in update/delete events, not only the key
ALTER TABLE shop.orders REPLICA IDENTITY FULL;

-- watch slot lag
SELECT slot_name, active,
       pg_size_pretty(pg_wal_lsn_diff(pg_current_wal_lsn(), confirmed_flush_lsn)) AS lag
FROM pg_replication_slots;
